function addUser(n) {
    [ inet:user?=$object.display_name ]
    [ <(refs)+ {yield $n} ]
    return()
}

[inet:email=$object.value]

if $object.display_name {
    $addUser($node)
}

[ <(refs)+ { it:sec:stix:bundle:id=$bundle.id } ]
$node.data.set(`stix:object:bundle:{$bundle.id}`, $object)
return($node)

file.storm:
($ok, $hash) = $lib.trycast(hash:sha256, $object.hashes."SHA-256")
if $ok {
    $guid = `sha256:{$hash}`
} else {
    $guid = `guid:{$lib.guid(stix, file, $object.id)}`
}
[
    file:bytes=$guid
    :size?=$object.size
    :name?=$object.name
    :mime?=$object.mime_type
    :md5?=$object.hashes."MD5"
    :sha1?=$object.hashes."SHA-1"
    :sha256?=$object.hashes."SHA-256"
    :sha512?=$object.hashes."SHA-512"
]

// TODO - Somehow check if a file-parser is installed and use those model extensions to save more about the file?

{ for $directory in $bundle.objects {
    if ($directory.id = $object.parent_directory_ref and $directory.type = "directory" and $object.name != $lib.null) {
        [ file:filepath=($guid, `{$directory.path}/{$object.name}`) ]
        [ <(refs)+ { it:sec:stix:bundle:id=$bundle.id } ]
    }
} }
// TODO - Do something with windows-pebinary-ext extension
[ <(refs)+ { it:sec:stix:bundle:id=$bundle.id } ]
$node.data.set(`stix:object:bundle:{$bundle.id}`, $object)
return($node)

