user-account.storm:
if (($object.account_type != $lib.null) and ($object.account_login != $lib.null)) {
    if ($object.account_type = "posix" or $object.account_type = "windows-local" or $object.account_type = "windows-domain") {
        [
            it:account=(stix, "user-account", $object.id)
            :user?=$object.account_login
        ]
        if ($object.account_type = "posix") {
            [ :posix:uid?=$object.user_id ]
        } else {
            [ :windows:sid?=$object.user_id ]
        }
    } elif ($object.account_type = "facebook" or $object.account_type = "skype" or $object.account_type = "twitter") {
        switch $object.account_type {
            facebook: {[inet:web:acct=(facebook.com, $object.account_login)]}
            skype: {[inet:web:acct=(skype.com, $object.account_login)]}
            twitter: {[inet:web:acct=(twitter.com, $object.account_login)]}
        }
    } else {
        [
            auth:creds=(stix, "user-account", $object.id)
            :user=$object.account_login
            :passwd?=$object.credential
        ]
    }
}

if (($node != $lib.null) and ($node.form() != "auth:creds")) {
    $acct = $node
    {
        | spin |
        [
            auth:creds=(stix, "user-account", $object.id)
            :user=$object.account_login
            :passwd?=$object.credential
        ]
        +auth:creds
        if ($object.account_type = "posix" or $object.account_type = "windows-local" or $object.account_type = "windows-domain") {
            [:account={yield $acct}]
        } else {
            [ +(refs)> { yield $acct } ]
        }
    }
}
[ <(refs)+ { it:sec:stix:bundle:id=$bundle.id } ]
$node.data.set(`stix:object:bundle:{$bundle.id}`, $object)
return($node)

vulnerability.storm:
/*
Example Stix 2.1 "vulnerability" object:
{
    "type": "vulnerability",
    "spec_version": "2.1",
    "id": "vulnerability--0c7b5b88-8ff7-4a4d-aa9d-feb398cd0061",
    "created": "2016-05-12T08:17:27.000Z",
    "modified": "2016-05-12T08:17:27.000Z",
    "name": "CVE-2016-1234",
    "description": "A buffer overflow in Example App allows remote attackers to execute arbitrary code.",
    "external_references": [
        { "source_name": "cve", "external_id": "CVE-2016-1234" }
    ]
}

Mapped to risk:vuln, which mirrors the reverse (export) mapping already used
by synapse.lib.stormlib.stix for risk:vuln <-> vulnerability (including
pulling the CVE id out of external_references into the :cve prop).
*/
[ risk:vuln=(stix, vulnerability, $object.id)
    :name?=$object.name
    :desc?=$object.description
]
{ for $ref in $object.external_references {
    if ($ref.source_name = "cve") {
        [ :cve?=$ref.external_id ]
    }
} }
[ <(refs)+ { it:sec:stix:bundle:id=$bundle.id } ]
$node.data.set(`stix:object:bundle:{$bundle.id}`, $object)
return($node)

windows-registry-key.storm:
/*
Example Stix 2.1 "windows-registry-key" object:
{
    "type": "windows-registry-key",
    "spec_version": "2.1",
    "id": "windows-registry-key--2ba37ae7-2745-5082-9dfd-9486dad41016",
    "key": "hkey_local_machine\\system\\bar\\foo",
    "values": [
        { "name": "Foo", "data": "qwerty", "data_type": "REG_SZ" }
    ]
}

Stix allows one key with multiple values, but it:dev:regval
models a single key+value pair per node, so this creates one node per entry
in "values" (or a single key-only node if "values" is empty/unset). Only the
last node created is returned/tracked by the ingest engine - a known
limitation of the one-node-per-object ingest model for this Stix type.
*/
if $object.values {
    // NOTE: intentionally NOT wrapped in a `{ }` subquery here (unlike the
    // usual loop convention elsewhere in this repo) - a subquery isolates
    // its pipeline from the outer one, which would prevent the created node
    // from ever binding to $node for the final return($node) below. Verified
    // against a live Cortex: wrapping this in `{ }` silently drops the node.
    for $regval in $object.values {
        [ it:dev:regval=(stix, windows-registry-key, $object.id, $regval.name)
            :key?=$object.key
            :str?=$regval.data
        ]
        [ <(refs)+ { it:sec:stix:bundle:id=$bundle.id } ]
        $node.data.set(`stix:object:bundle:{$bundle.id}`, $object)
    }
} else {
    [ it:dev:regval=(stix, windows-registry-key, $object.id)
        :key?=$object.key
    ]
    [ <(refs)+ { it:sec:stix:bundle:id=$bundle.id } ]
    $node.data.set(`stix:object:bundle:{$bundle.id}`, $object)
}
return($node)

x509-certificate.storm:
[ crypto:x509:cert=(stix, x509-certificate, $object.id)
    :serial?=$object.serial_number
    :version?=$object.version
    :algo?=$object.signature_algorithm
    :issuer?=$object.issuer
    :subject?=$object.subject
    :validity:notbefore?=$object.validity_not_before
    :validity:notafter?=$object.validity_not_after
]

if $object.hashes {
    [ :md5?=$object.hashes.MD5
      :sha1?=$object.hashes."SHA-1"
      :sha256?=$object.hashes."SHA-256"
    ]
    if $object.hashes."SHA-256" {
        [ :file?=$object.hashes."SHA-256" ]
    }
}

[ <(refs)+ { it:sec:stix:bundle:id=$bundle.id } ]
$node.data.set(`stix:object:bundle:{$bundle.id}`, $object)
return($node)
